package busclient

import (
	"bytes"
	"context"
	"fmt"
	"go/format"
	"reflect"
	"sort"
	"strings"
)

// Spec says what client to generate.
type Spec struct {
	// Package is the generated file's package name.
	Package string
	// Iface is the service interface, e.g. reflect.TypeOf((*api.X)(nil)).Elem().
	Iface reflect.Type
	// Imports names the alias of every package whose types appear in the
	// interface's signatures (context excepted), by import path.
	Imports map[string]string
}

var (
	ctxType = reflect.TypeOf((*context.Context)(nil)).Elem()
	errType = reflect.TypeOf((*error)(nil)).Elem()
)

// Generate writes the client for spec.Iface: a `Client` type holding a
// *Client, implementing the interface with one Call per request/reply method
// — `(ctx, In) (Out, error)` — and a NotOverTheBus refusal for any other shape.
// The output is gofmt'ed and byte-stable (methods in name order).
func Generate(spec Spec) ([]byte, error) {
	if spec.Iface == nil || spec.Iface.Kind() != reflect.Interface {
		return nil, fmt.Errorf("busclient.Generate: Iface must be an interface type")
	}
	g := &gen{imports: spec.Imports, used: map[string]bool{}}
	ifaceName, err := g.typeString(spec.Iface)
	if err != nil {
		return nil, err
	}
	var methods bytes.Buffer
	for i := 0; i < spec.Iface.NumMethod(); i++ {
		m := spec.Iface.Method(i)
		if err := g.method(&methods, m); err != nil {
			return nil, fmt.Errorf("busclient.Generate: %s: %w", m.Name, err)
		}
	}

	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by busclient.Generate from %s.%s; DO NOT EDIT.\n\n", spec.Iface.PkgPath(), spec.Iface.Name())
	fmt.Fprintf(&b, "package %s\n\n", spec.Package)
	b.WriteString("import (\n\t\"context\"\n\n\t\"github.com/katyoti/katyoti-fwk/internal/appcore/busclient\"\n")
	paths := make([]string, 0, len(g.used))
	for p := range g.used {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		fmt.Fprintf(&b, "\t%s %q\n", spec.Imports[p], p)
	}
	b.WriteString(")\n\n")
	fmt.Fprintf(&b, "// Client implements %s over the message bus: each method is one\n", ifaceName)
	b.WriteString("// round-trip to the binary hosting the service.\n")
	b.WriteString("type Client struct{ c *busclient.Client }\n\n")
	b.WriteString("// NewClient returns the client for the service c addresses.\n")
	b.WriteString("func NewClient(c *busclient.Client) Client { return Client{c: c} }\n\n")
	fmt.Fprintf(&b, "var _ %s = Client{}\n\n", ifaceName)
	b.Write(methods.Bytes())
	return format.Source(b.Bytes())
}

type gen struct {
	imports map[string]string
	used    map[string]bool
}

func (g *gen) method(w *bytes.Buffer, m reflect.Method) error {
	t := m.Type
	params := make([]string, t.NumIn())
	for i := 0; i < t.NumIn(); i++ {
		s, err := g.typeString(t.In(i))
		if err != nil {
			return err
		}
		params[i] = s
	}
	results := make([]string, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		s, err := g.typeString(t.Out(i))
		if err != nil {
			return err
		}
		results[i] = s
	}
	names := []string{"ctx", "in"}
	var sig []string
	for i, p := range params {
		name := fmt.Sprintf("a%d", i)
		if i < len(names) {
			name = names[i]
		}
		sig = append(sig, name+" "+p)
	}
	res := strings.Join(results, ", ")
	if len(results) > 1 {
		res = "(" + res + ")"
	}
	fmt.Fprintf(w, "func (x Client) %s(%s) %s {\n", m.Name, strings.Join(sig, ", "), res)
	if t.NumIn() == 2 && t.In(0) == ctxType && t.NumOut() == 2 && t.Out(1) == errType {
		fmt.Fprintf(w, "\treturn busclient.Call[%s](ctx, x.c, %q, in)\n}\n\n", results[0], m.Name)
		return nil
	}
	// Not a request/reply: a zero value per result, the refusal as the error.
	zeros := make([]string, 0, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		if t.Out(i) == errType {
			zeros = append(zeros, fmt.Sprintf("x.c.NotOverTheBus(%q)", m.Name))
			continue
		}
		zeros = append(zeros, zeroOf(t.Out(i), results[i]))
	}
	fmt.Fprintf(w, "\treturn %s\n}\n\n", strings.Join(zeros, ", "))
	return nil
}

// typeString renders t as source, qualifying named types by their alias.
func (g *gen) typeString(t reflect.Type) (string, error) {
	if t == ctxType {
		return "context.Context", nil
	}
	if t == errType {
		return "error", nil
	}
	if t.Name() != "" {
		if t.PkgPath() == "" {
			return t.Name(), nil // predeclared
		}
		alias, ok := g.imports[t.PkgPath()]
		if !ok {
			return "", fmt.Errorf("no import alias for %s (type %s)", t.PkgPath(), t.Name())
		}
		g.used[t.PkgPath()] = true
		return alias + "." + t.Name(), nil
	}
	switch t.Kind() {
	case reflect.Pointer:
		s, err := g.typeString(t.Elem())
		return "*" + s, err
	case reflect.Slice:
		s, err := g.typeString(t.Elem())
		return "[]" + s, err
	case reflect.Map:
		k, err := g.typeString(t.Key())
		if err != nil {
			return "", err
		}
		v, err := g.typeString(t.Elem())
		return "map[" + k + "]" + v, err
	case reflect.Chan:
		s, err := g.typeString(t.Elem())
		switch t.ChanDir() {
		case reflect.RecvDir:
			return "<-chan " + s, err
		case reflect.SendDir:
			return "chan<- " + s, err
		}
		return "chan " + s, err
	case reflect.Func:
		var in, out []string
		for i := 0; i < t.NumIn(); i++ {
			s, err := g.typeString(t.In(i))
			if err != nil {
				return "", err
			}
			in = append(in, s)
		}
		for i := 0; i < t.NumOut(); i++ {
			s, err := g.typeString(t.Out(i))
			if err != nil {
				return "", err
			}
			out = append(out, s)
		}
		s := "func(" + strings.Join(in, ", ") + ")"
		switch len(out) {
		case 0:
		case 1:
			s += " " + out[0]
		default:
			s += " (" + strings.Join(out, ", ") + ")"
		}
		return s, nil
	}
	return "", fmt.Errorf("unsupported type %s", t)
}

func zeroOf(t reflect.Type, src string) string {
	switch t.Kind() {
	case reflect.Pointer, reflect.Slice, reflect.Map, reflect.Chan, reflect.Func, reflect.Interface:
		return "nil"
	case reflect.String:
		return `""`
	case reflect.Bool:
		return "false"
	case reflect.Struct, reflect.Array:
		return src + "{}"
	}
	return "0"
}
